SELECT DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, region, CASE WHEN sqft >= 15507 THEN 'high' WHEN sqft >= 3143 THEN 'mid' ELSE 'low' END AS sqft_bucket, MIN(sqft) AS min_sqft, COUNT(CASE WHEN city = 'New York' THEN 1 END) AS new_york_count FROM stores WHERE city = 'Bangkok' GROUP BY opened_month, region, sqft_bucket HAVING COUNT(CASE WHEN city = 'New York' THEN 1 END) >= 1 ORDER BY region ASC, min_sqft DESC
